const deliveryLabels={web:'Play in browser',download:'Download full experience',desktop:'Run in desktop app',external:'External platform'};
function safeLink(value){try{const u=new URL(value);return u.protocol==='https:'&&!u.username&&!u.password?u.href:''}catch{return ''}}
function cityModel(tax){return {population:Math.round(128-(tax-12)*2.8),happiness:Math.max(15,Math.round(88-(tax-8)*3)),revenue:Math.round(tax*(128-(tax-12)*2.8)*.8)}}
const city={contentType:'interactive',id:'city',cat:'Simulation',title:'Micro City: how would you run a city?',desc:'Try a 20-second tax experiment. The full desktop city is a concept demo.',author:'Little Worlds',time:'20 sec experiment',likes:426,plays:'18.2k',bg:'#e0ebdb',delivery:{type:'download',size:'2.4 GB',systems:'Windows / macOS',notes:'The planned desktop game includes city building, traffic, and long-term management. Installers are not available yet.',demo:true}};
works.unshift(city);works.find(w=>w.id==='orbit').delivery={type:'desktop',size:'860 MB',systems:'Windows / macOS',appId:'kepler-orbital-lab',notes:'The planned desktop app will let you find Gravity Lab in your Library and install the full experience.',demo:true};
const priorStage=stage;stage=function(w){if(w.id!=='city')return priorStage(w);const m=cityModel(12);return `<div class="slice city-slice"><div class="city-label">MICRO CITY / POLICY EXPERIMENT</div><h3>One city. Three trade-offs.</h3><div class="city-metrics"><div><span>Population / thousands</span><strong data-city-pop>${m.population}</strong></div><div><span>Happiness</span><strong data-city-happy>${m.happiness}%</strong></div><div><span>Revenue / 10k</span><strong data-city-money>${m.revenue}</strong></div></div><div class="city-bar"><i style="width:${m.happiness}%"></i></div><label>Tax rate <input type="range" aria-label="City tax rate" min="5" max="25" value="12" data-city-tax><output>12%</output></label><small>Adjust the tax rate · Simplified demo model</small></div>`};
document.addEventListener('input',e=>{if(!e.target.matches('[data-city-tax]'))return;const el=e.target.closest('.city-slice'),tax=+e.target.value,m=cityModel(tax);el.querySelector('output').textContent=tax+'%';el.querySelector('[data-city-pop]').textContent=m.population;el.querySelector('[data-city-happy]').textContent=m.happiness+'%';el.querySelector('[data-city-money]').textContent=m.revenue;el.querySelector('.city-bar i').style.width=m.happiness+'%'});
const storedLibrary=readStored('slice-library-v1',[]);let libraryIds=new Set((Array.isArray(storedLibrary)?storedLibrary:[]).filter(id=>typeof id==='string'));let libraryFilter='all';
const libraryButton=document.createElement('button');libraryButton.id='library-entry';libraryButton.innerHTML='▱ Library <span>0</span>';document.querySelector('#publish-entry').before(libraryButton);
const libraryDialog=document.createElement('dialog');libraryDialog.id='library-dialog';libraryDialog.setAttribute('aria-labelledby','library-title');document.body.append(libraryDialog);
function updateLibraryCount(){libraryButton.querySelector('span').textContent=works.filter(w=>libraryIds.has(w.id)).length}
function toggleLibrary(id){const next=new Set(libraryIds);next.has(id)?next.delete(id):next.add(id);try{localStorage.setItem('slice-library-v1',JSON.stringify([...next]))}catch{toast('Could not save to Library. Check your browser storage.');return}libraryIds=next;render();if(dialog.open)decorateWork(works.find(w=>w.id===activeId));if(libraryDialog.open)renderLibrary();toast(libraryIds.has(id)?'Saved to your local Library.':'Removed from Library.')}
const priorRender=render;render=function(){priorRender();document.querySelectorAll('#feed .card').forEach(card=>{const w=works.find(w=>'card-'+w.id===card.id),d=w.delivery||{type:'web'};const badge=document.createElement('div');badge.className='delivery-badge';badge.textContent=(d.type==='web'?'◎ ':'↗ ')+(deliveryLabels[d.type]||deliveryLabels.web)+(d.demo?' · Concept demo':'');card.querySelector('.card-meta').before(badge);const save=document.createElement('button');save.className='save-work'+(libraryIds.has(w.id)?' saved':'');save.dataset.save=w.id;save.setAttribute('aria-pressed',String(libraryIds.has(w.id)));save.textContent=libraryIds.has(w.id)?'✓ Saved':'＋ Library';card.querySelector('.card-actions').insertBefore(save,card.querySelector('[data-open]'));if(d.type!=='web')card.querySelector('[data-open]').textContent='Full experience ↗'});updateLibraryCount()};
const deliveryBanner=document.createElement('section');deliveryBanner.className='app-downloads';deliveryBanner.setAttribute('aria-label','Get the Slice app');deliveryBanner.innerHTML=`<article class="app-download-card"><div class="app-platform">SLICE FOR MOBILE <span>iOS / Android</span></div><h2>Take curiosity with you.</h2><p>Discover and play new experiences anywhere. Save your favorites to Library for another time.</p><div class="app-download-bottom"><button class="dark" type="button" disabled>Mobile app · Coming soon</button><span>Discover · Play · Save</span></div></article><article class="app-download-card desktop-download"><div class="app-platform">SLICE FOR DESKTOP <span>Windows / macOS</span></div><h2>More room to play.</h2><p>A future home for bigger games, simulations, and creative tools. Bring your Library to the desktop.</p><div class="app-download-bottom"><button class="dark" type="button" disabled>Desktop app · Coming soon</button><span>Download · Play · Manage</span></div></article><p class="app-download-note">Planned apps · Downloads and cross-device sync are not available yet.</p>`;document.querySelector('main#discover').append(deliveryBanner);
function linkButton(url,text){const safe=safeLink(url);return safe?`<a class="runtime-link" href="${escapeHtml(safe)}" target="_blank" rel="noopener noreferrer">${text} ↗</a>`:''}
function decorateWork(w){document.querySelector('#full-work-panel')?.remove();if(!w)return;const d=w.delivery||{type:'web'};document.querySelector('#dialog-mode').textContent=d.type==='web'?'PLAYGROUND · Browser experience':'INTERACTIVE SLICE · Full experience below';const panel=document.createElement('section');panel.id='full-work-panel';let actions='';if(d.type==='download'){actions=linkButton(d.windows,'Download for Windows')+linkButton(d.mac,'Download for macOS');if(!actions)actions='<p class="runtime-empty">Concept demo：No installer is available yet. No download will start.</p>'}else if(d.type==='desktop'){actions='<button type="button" class="dark" data-instructions>Desktop instructions →</button>'}else if(d.type==='external'){actions=linkButton(d.url,'Open external platform')||'<p class="runtime-empty">The creator has not added a platform link yet.</p>'}else if(d.url){actions=linkButton(d.url,'Open full web experience')}else{actions='<p class="runtime-empty">Keep playing above. No installation needed.</p>'}panel.innerHTML=`<div class="full-heading"><div><span class="eyebrow">THE FULL EXPERIENCE</span><h3>${deliveryLabels[d.type]||deliveryLabels.web}</h3></div><button data-save="${w.id}" aria-pressed="${libraryIds.has(w.id)}">${libraryIds.has(w.id)?'✓ Saved to Library':'＋ Save to Library'}</button></div><div class="runtime-meta"><span>${escapeHtml(d.systems||'Mobile / Web')}</span>${d.size?`<span>${escapeHtml(d.size)}</span>`:''}<span>${d.type==='web'?'No installation needed':'Saved ≠ installed'}</span></div><p>${escapeHtml(d.notes||(d.type==='web'?'Explore this Slice in your browser.':'Save it now. Continue on a compatible device.'))}</p><div class="runtime-actions">${actions}</div><div class="desktop-instructions" hidden><h4>Continue on desktop</h4><ol><li>Open the Slice desktop app and sign in.</li><li>Find your saved experience in Library.</li><li>Check the requirements, install, and launch.</li></ol>${d.appId?`<p>Slice ID: ${escapeHtml(d.appId)}</p>`:''}<p class="prototype-note">This previews a future flow. Desktop apps, account sync, and installation are not connected yet.</p></div>`;document.querySelector('#dialog-stage').after(panel);panel.querySelector('[data-instructions]')?.addEventListener('click',()=>{const box=panel.querySelector('.desktop-instructions');box.hidden=!box.hidden;panel.querySelector('[data-instructions]').textContent=box.hidden?'Desktop instructions →':'Hide instructions ↑'})}
const priorOpenWork=openWork;openWork=function(id,remix=false){const w=works.find(w=>w.id===id);if(remix&&id==='city'){toast('This city is a concept demo. Start your own experience with a playable template.');return}document.querySelector('#full-work-panel')?.remove();priorOpenWork(id,remix);if(w&&!remix)decorateWork(w)};
function renderLibrary(){const list=works.filter(w=>libraryIds.has(w.id));const shown=list.filter(w=>libraryFilter==='all'||(libraryFilter==='desktop'&&['desktop','download'].includes(w.delivery?.type))||(libraryFilter==='web'&&(!w.delivery||w.delivery.type==='web')));libraryDialog.innerHTML=`<div class="dialog-head"><span>YOUR INTERACTIVE LIBRARY</span><button data-close-library aria-label="Close Library">✕</button></div><h2 id="library-title">Save it for your next moment of curiosity.</h2><p>Your playable discoveries, all in one place.</p><div class="library-summary"><strong>${list.length} saved experiences</strong><span>${list.filter(w=>['download','desktop'].includes(w.delivery?.type)).length} desktop experiences</span><span>Saved locally · Cross-device sync coming later</span></div><div class="library-filters"><button data-lib-filter="all" aria-pressed="${libraryFilter==='all'}">All</button><button data-lib-filter="desktop" aria-pressed="${libraryFilter==='desktop'}">For desktop</button><button data-lib-filter="web" aria-pressed="${libraryFilter==='web'}">Play in browser</button></div><div class="library-list">${shown.map(w=>{const d=w.delivery||{type:'web'};return `<article class="library-item"><div class="library-mark">${d.type==='web'?'◎':'↗'}</div><div><span>${escapeHtml(deliveryLabels[d.type]||deliveryLabels.web)}${d.size?' · '+escapeHtml(d.size):''}</span><h3>${escapeHtml(w.title)}</h3><p>${escapeHtml(w.author)} · Saved${d.type!=='web'?' / Not installed':''}</p></div><div class="library-item-actions"><button class="dark" data-library-open="${w.id}">${d.type==='web'?'Continue playing':'View options'} ↗</button><button data-save="${w.id}">Remove</button></div></article>`}).join('')||'<div class="library-empty"><span>▱</span><h3>Make room for your next discovery.</h3><p>Select + Library on a playable experience to save it here.</p><button data-close-library>Discover experiences →</button></div>'}</div><div class="library-foot"><strong>Your collection starts here.</strong><p>Saving adds an experience to your list. It does not purchase, download, or install it. Account sync is planned for a future release.</p></div>`}
libraryButton.onclick=()=>{renderLibrary();libraryDialog.showModal()};document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.save)toggleLibrary(b.dataset.save);if(b.hasAttribute('data-close-library'))libraryDialog.close();if(b.dataset.libFilter){libraryFilter=b.dataset.libFilter;renderLibrary()}if(b.dataset.libraryOpen){libraryDialog.close();openWork(b.dataset.libraryOpen)}});
const deliveryFields=document.createElement('fieldset');deliveryFields.className='delivery-fields';deliveryFields.innerHTML=`<legend>Where does the full experience run?</legend><p>The playable preview appears in the Feed. Choose how people can explore further.</p><label>Delivery method <select name="deliveryType"><option value="web">Play in browser</option><option value="download">Download full experience</option><option value="desktop">Run in desktop app</option><option value="external">External platform</option></select></label><div data-delivery-fields="web external"><label>Full experience URL <input name="deliveryUrl" type="url" placeholder="https://…"></label><small>Optional for browser experiences. Required for external platforms.</small></div><div data-delivery-fields="download"><label>Windows download URL <input name="deliveryWindows" type="url" placeholder="https://…"></label><label>macOS download URL <input name="deliveryMac" type="url" placeholder="https://…"></label><small>Add at least one valid HTTPS download URL.</small></div><div data-delivery-fields="desktop"><label>Desktop Slice ID <input name="deliveryAppId" maxlength="80" placeholder="e.g. my-interactive-world"></label><small>Instructions only. The desktop app is not connected yet.</small></div><div data-delivery-fields="download desktop"><label>Supported systems <input name="deliverySystems" maxlength="80" placeholder="e.g. Windows 11 / macOS 14+"></label><label>Download size <input name="deliverySize" maxlength="30" placeholder="e.g. 2.4 GB"></label><label>Installation and launch instructions <textarea name="deliveryNotes" maxlength="600" rows="3" placeholder="Explain how to explore the full experience"></textarea></label></div>`;document.querySelector('.publish-fields').append(deliveryFields);
function syncDeliveryFields(){const mode=publishForm.elements.deliveryType.value;deliveryFields.querySelectorAll('[data-delivery-fields]').forEach(el=>{el.hidden=!el.dataset.deliveryFields.split(' ').includes(mode);el.querySelectorAll('input,textarea').forEach(input=>input.disabled=el.hidden)})}
publishForm.elements.deliveryType.onchange=syncDeliveryFields;syncDeliveryFields();
const previousFormData=formData;formData=function(){const d=previousFormData(),f=publishForm.elements;return {...d,delivery:{type:f.deliveryType.value,url:f.deliveryUrl.value.trim(),windows:f.deliveryWindows.value.trim(),mac:f.deliveryMac.value.trim(),appId:f.deliveryAppId.value.trim(),systems:f.deliverySystems.value.trim(),size:f.deliverySize.value.trim(),notes:f.deliveryNotes.value.trim()}}};
const previousCreator=openCreator;openCreator=function(work){previousCreator(work);const d=(work||readStored(draftKey,null))?.delivery;if(d){const mapping={deliveryType:'type',deliveryUrl:'url',deliveryWindows:'windows',deliveryMac:'mac',deliveryAppId:'appId',deliverySystems:'systems',deliverySize:'size',deliveryNotes:'notes'};for(const [field,key] of Object.entries(mapping))publishForm.elements[field].value=d[key]||'';if(!deliveryLabels[publishForm.elements.deliveryType.value])publishForm.elements.deliveryType.value='web'}syncDeliveryFields()};
const previousPublish=publishForm.onsubmit;publishForm.onsubmit=e=>{const d=formData().delivery;let error='';if(d.type==='download'&&!d.windows&&!d.mac)error='Add a download URL for at least one operating system.';if(d.type==='external'&&!d.url)error='Enter the external platform URL.';if(d.type==='desktop'&&!d.appId)error='Enter the desktop Slice ID.';const urls=d.type==='download'?[d.windows,d.mac]:['web','external'].includes(d.type)?[d.url]:[];if(urls.some(u=>u&&!safeLink(u)))error='Use a valid HTTPS URL without a username or password.';if(error){e.preventDefault();document.querySelector('#publish-error').textContent=error;return}previousPublish(e);syncDeliveryFields()};
render();if(location.hash==='#library'){renderLibrary();libraryDialog.showModal()}else if(location.hash.startsWith('#work=')){openWork(location.hash.slice(6))}
window.addEventListener('hashchange',()=>{if(location.hash==='#library'){renderLibrary();if(!libraryDialog.open)libraryDialog.showModal()}});
